<script setup lang="ts">
import {ref,computed,watch,onUnmounted} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {ElMessage} from 'element-plus'
import {api,fmt} from '../api'
import {jobNames} from '../platform'
import {useWorkspace} from '../store'
import Status from '../components/Status.vue'
import Icon from '../components/Icon.vue'
import FailureTriage from '../components/FailureTriage.vue'
const route=useRoute(),router=useRouter(),store=useWorkspace(),items=ref<any[]>([]),total=ref(0),page=ref(1),kind=ref(''),status=ref(''),search=ref(''),job=ref<any>(null),tab=ref('result'),id=computed(()=>route.params.id)
async function load(){if(!store.projectId)return;if(id.value){let {data}=await api.get(`jobs/${id.value}/`);if(data.status==='completed'&&['api','ui'].includes(data.kind)&&!data.result?.run_report_id&&store.canEdit){try{const generated=await api.post(`jobs/${id.value}/generate_report/`);data={...data,result:{...data.result,run_report_id:generated.data.run_report_id}}}catch{}}job.value=data}else{const {data}=await api.get('jobs/',{params:{project:store.projectId,kind:kind.value,status:status.value,search:search.value,page:page.value}});items.value=data.results;total.value=data.count}}
watch(()=>[id.value,store.projectId],()=>{job.value=null;load()},{immediate:true})
const timer=setInterval(()=>{if(job.value&&['queued','running','awaiting_approval'].includes(job.value.status)||!id.value&&items.value.some(j=>['queued','running','awaiting_approval'].includes(j.status)))load()},2500);onUnmounted(()=>clearInterval(timer))
async function action(name:string,body:any={}){await api.post(`jobs/${job.value.id}/${name}/`,body);ElMessage.success('操作已保存');load()}
const triaging=ref(false)
async function triage(){
  if(triaging.value)return
  triaging.value=true
  try{const {data}=await api.post(`jobs/${job.value.id}/triage/`);await router.push('/tasks/'+data.id)}
  finally{triaging.value=false}
}
function filter(){page.value=1;load()}
const previewFiles=computed(()=>[...(job.value?.files||[])].filter((f:any)=>['screenshot','video'].includes(f.category)).sort((a:any,b:any)=>a.id-b.id))
const screenshotFiles=computed(()=>previewFiles.value.filter((f:any)=>f.category==='screenshot'))
const otherFiles=computed(()=>job.value?.files?.filter((f:any)=>!['screenshot','video'].includes(f.category))||[])
const screenshotUrls=computed(()=>screenshotFiles.value.map((f:any)=>inlineUrl(f)))
function inlineUrl(file:any){return `${file.url}${file.url.includes('?')?'&':'?'}inline=1`}
function screenshotIndex(file:any){return screenshotFiles.value.findIndex((image:any)=>image.id===file.id)}
</script>
<template><div v-if="!id"><div class="page-heading"><div><div class="heading-eyebrow">TASK CONTROL CENTER</div><h1>{{ $t('任务中心') }}<span class="heading-tag">{{total}}</span></h1><p>{{ $t('统一追踪智能生成、需求评审、文档索引、接口与 UI 自动化。') }}</p></div><div class="inline-actions"><el-button @click="router.push('/runs')">{{ $t('测试报告') }}</el-button><el-button type="primary" @click="router.push('/ai')"><Icon name="Plus"/>{{ $t('创建智能任务') }}</el-button></div></div><section class="panel"><div class="list-toolbar"><h3>{{ $t('全部任务') }}</h3><div class="inline-actions"><el-input v-model="search" :placeholder="$t('搜索任务')" clearable @keyup.enter="filter" @clear="filter" style="width:180px"/><el-select v-model="kind" clearable :placeholder="$t('全部类型')" style="width:150px" @change="filter"><el-option v-for="(label,k) in jobNames" :key="k" :label="label" :value="k"/></el-select><el-select v-model="status" clearable :placeholder="$t('全部状态')" style="width:130px" @change="filter"><el-option v-for="(label,k) in {queued:'排队中',running:'运行中',completed:'已完成',failed:'失败',awaiting_approval:'待审批',cancelled:'已取消'}" :key="k" :label="label" :value="k"/></el-select><el-button @click="filter">{{ $t('查询') }}</el-button></div></div><el-table :data="items"><el-table-column :label="$t('任务')" min-width="230"><template #default="{row}"><div class="table-title"><span class="table-icon"><Icon name="Operation"/></span><div><el-button class="asset-name" link @click="router.push('/tasks/'+row.id)">{{row.name}}</el-button><small>#{{row.id}} · {{$t(jobNames[row.kind])}}</small></div></div></template></el-table-column><el-table-column :label="$t('模式')" width="100"><template #default="{row}"><span class="mode-pill">{{row.mode==='live'?'真实执行':row.mode==='local'?'本地处理':'模拟模式'}}</span></template></el-table-column><el-table-column :label="$t('状态')" width="105"><template #default="{row}"><Status :value="row.status"/></template></el-table-column><el-table-column :label="$t('进度')" width="140"><template #default="{row}"><el-progress :percentage="row.progress" :stroke-width="5"/></template></el-table-column><el-table-column :label="$t('创建时间')" width="140"><template #default="{row}">{{fmt(row.created_at)}}</template></el-table-column><el-table-column :label="$t('操作')" width="75"><template #default="{row}"><el-button link type="primary" @click="router.push('/tasks/'+row.id)">{{ $t('详情') }}</el-button></template></el-table-column></el-table><div class="pagination"><span>共 {{total}} 条</span><el-pagination v-model:current-page="page" :total="total" layout="prev,pager,next" @current-change="load"/></div></section></div>
<div v-else-if="job"><el-button link class="back-button" @click="router.push('/tasks')">{{ $t('← 返回任务中心') }}</el-button><div class="page-heading"><div><div class="heading-eyebrow">TASK #{{job.id}} · {{jobNames[job.kind]}}</div><h1>{{job.name}}</h1><p>{{fmt(job.created_at)}} · {{job.mode==='live'?'真实执行':job.mode==='local'?'本地处理':'模拟模式'}}</p></div><div class="inline-actions"><el-button v-if="['queued','running','awaiting_approval'].includes(job.status)&&store.canEdit" @click="action('cancel')">{{ $t('取消') }}</el-button><el-button v-if="job.status==='completed'&&job.result.run_report_id" type="primary" plain @click="router.push('/runs/'+job.result.run_report_id)">{{ $t('查看测试报告') }}</el-button><el-button v-if="job.status==='completed'&&['api','ui'].includes(job.kind)&&job.mode==='live'&&job.result.cases?.some((item:any)=>item.status==='failed')" @click="router.push({path:'/ai',query:{operation:'analyze',job:job.id,case_id:job.result.cases.find((item:any)=>item.status==='failed').id,target:job.kind}})">{{ $t('AI 失败分析') }}</el-button><el-button v-if="store.canEdit&&job.status==='completed'&&['api','ui'].includes(job.kind)&&job.mode==='live'&&job.result.cases?.some((item:any)=>item.status==='failed')" :loading="triaging" @click="triage">失败分诊</el-button><el-button v-if="job.kind==='triage'&&job.result.source_job_id" @click="router.push('/tasks/'+job.result.source_job_id)">查看原执行任务</el-button><a v-if="job.kind==='design'" :href="`/api/jobs/${job.id}/export/?download=markdown`" class="button-link">导出 Markdown</a><a :href="`/api/jobs/${job.id}/export/`" class="button-link">{{ $t('导出报告') }}</a></div></div><section class="panel task-summary"><div class="inline-actions"><Status :value="job.status"/><span class="muted">{{job.usage.total_tokens||0}} Token · {{job.usage.calls||0}} 次模型调用</span></div><el-progress :percentage="job.progress"/><div v-if="job.result.summary" class="knowledge-stats"><div v-for="(v,k) in job.result.summary" :key="k"><b>{{v}}</b><span>{{({total:'总数',passed:'通过',failed:'失败',skipped:'跳过'} as any)[k]}}</span></div></div><el-alert v-if="job.result.error" type="error" :closable="false" :title="job.result.error"/><p v-if="job.status==='queued'" class="helper">{{ $t('等待 Worker 领取。若持续排队，请检查后台 Worker 是否运行。') }}</p><template v-if="job.status==='awaiting_approval'"><p class="helper">{{ $t('即将调用 MCP 工具，下面的服务、工具名与参数即为实际调用内容。项目管理员可批准或拒绝。') }}</p><pre class="json-result">{{JSON.stringify({resource:job.payload.resource_id,tool:job.payload.tool,arguments:job.payload.arguments},null,2)}}</pre><div v-if="store.project?.role==='owner'" class="inline-actions"><el-button type="primary" @click="action('approve',{approve:true})">{{ $t('批准本次工具调用') }}</el-button><el-button @click="action('approve',{approve:false})">{{ $t('拒绝') }}</el-button></div></template></section><FailureTriage :data="job.result.triage"/><el-alert v-if="job.result.failure_analysis_jobs?.length" type="info" :closable="false" title="已为失败用例创建 AI 分析任务"><template #default><el-button v-for="item in job.result.failure_analysis_jobs" :key="item.job_id" link type="primary" @click="router.push('/tasks/'+item.job_id)">查看用例 #{{item.case_id}} 分析 · 任务 #{{item.job_id}}</el-button></template></el-alert><el-alert v-if="job.result.failure_analysis_error" type="warning" :closable="false" :title="job.result.failure_analysis_error"/><section class="panel report-panel"><el-tabs v-model="tab"><el-tab-pane name="result" :label="$t('执行结果')"><div v-if="job.result.cases"><div v-if="job.result.stability?.length" class="knowledge-stats"><div v-for="item in job.result.stability" :key="item.case_id"><b :class="item.stable?'text-green':'text-red'">{{item.pass_rate}}%</b><span>稳定性 · {{item.passed}}/{{item.repeat_count}} 轮通过 · {{item.stall_count}} 次卡顿 · {{item.page_error_count}} 次页面异常</span></div></div><el-collapse><el-collapse-item v-for="c in job.result.cases" :key="`${c.id}-${c.iteration||1}`" :title="`${c.status==='passed'?'✓':c.status==='failed'?'✕':'–'} ${c.name}${c.iteration?` · 第 ${c.iteration} 轮`:``}`"><pre class="json-result">{{JSON.stringify(c,null,2)}}</pre><el-button v-if="c.status==='failed'&&job.status==='completed'&&['api','ui'].includes(job.kind)&&job.mode==='live'" type="primary" plain @click="router.push({path:'/ai',query:{operation:'analyze',job:job.id,case_id:c.id,target:job.kind}})">分析此失败用例</el-button></el-collapse-item></el-collapse></div><div v-else-if="job.kind==='design'&&job.result.output?.breakdown"><h3>一、需求文档功能拆分</h3><el-collapse><el-collapse-item v-for="m in job.result.output.breakdown" :key="m.id" :title="`${m.name} · ${m.functions.length} 个节点`"><article v-for="f in m.functions" :key="f.id" class="generated-case"><h4>{{f.name}}（{{f.id}}）</h4><p v-for="(label,key) in {preconditions:'前置条件',flow:'操作流程',validation:'校验规则',errors:'异常提示',special:'特殊逻辑',open_questions:'待确认'}" :key="key" v-show="f[key]?.length"><strong>{{label}}：</strong>{{f[key]?.join('；')}}</p><el-collapse><el-collapse-item title="需求原文"><pre class="json-result">{{f.source_text}}</pre></el-collapse-item></el-collapse></article></el-collapse-item></el-collapse><h3 style="margin-top:22px">二、{{job.result.output.focus_module}}测试用例</h3><el-table v-if="job.result.output.cases?.length" :data="job.result.output.cases" border><el-table-column prop="case_id" label="用例ID" width="95"/><el-table-column prop="feature" label="测试模块" width="115"/><el-table-column prop="scenario" label="测试场景" min-width="145"/><el-table-column prop="preconditions" label="前置条件" min-width="170"/><el-table-column label="操作步骤" min-width="190"><template #default="{row}">{{row.steps?.[0]?.action}}</template></el-table-column><el-table-column prop="expected" label="预期结果" min-width="200"/><el-table-column prop="type" label="用例类型" width="115"/></el-table><p v-if="job.result.output.notice" class="helper">{{job.result.output.notice}}</p></div><section v-else-if="job.kind==='app_video'&&job.result.case_id"><el-alert :type="job.result.automation_status==='ready'?'success':'warning'" :title="job.result.automation_status==='ready'?'App 用例已生成，尚未验证':'已生成用例草稿，部分操作需要补充定位字段'" :closable="false" show-icon/><p class="helper">{{job.result.case_name}} · 用例 #{{job.result.case_id}} · 识别只依据关键帧，未在真实设备执行。请检查步骤、字段定位和运行时输入变量。</p><el-table :data="job.result.steps||[]"><el-table-column type="index" label="#" width="60"/><el-table-column prop="action" label="操作" width="150"/><el-table-column label="定位字段 / 内容" min-width="220"><template #default="{row}">{{row.locator?JSON.stringify(row.locator):row.value||''}}</template></el-table-column><el-table-column prop="recognition_evidence" label="画面依据" min-width="200"/></el-table><el-alert v-if="job.result.recognition_issues?.length" title="待确认事项" type="warning" :closable="false"><template #default><ul><li v-for="(issue,index) in job.result.recognition_issues" :key="index">{{issue}}</li></ul></template></el-alert><el-button type="primary" @click="router.push('/ui-testing?platform=app')">查看 App 用例</el-button></section><pre v-else class="json-result">{{JSON.stringify(job.result.output||job.result,null,2)}}</pre><el-button v-if="job.status==='completed'&&!job.applied&&(job.result.output?.cases?.length||job.result.output?.requirements)&&store.canEdit" type="primary" @click="action('apply')">{{ $t('应用到资产') }}</el-button><p v-if="job.applied" class="text-green">{{ $t('结果已写入资产') }}</p></el-tab-pane><el-tab-pane name="logs" :label="$t('流程与日志')"><el-timeline><el-timeline-item v-for="(l,i) in job.logs" :key="i" :timestamp="fmt(l.at)"><strong>{{l.stage}}</strong><p>{{l.message}}</p></el-timeline-item></el-timeline><h3>{{ $t('状态历史') }}</h3><pre class="json-result">{{JSON.stringify(job.history,null,2)}}</pre></el-tab-pane><el-tab-pane name="sources" :label="$t('输入与引用')"><h3>{{ $t('任务输入快照') }}</h3><pre class="json-result">{{JSON.stringify(job.payload,null,2)}}</pre><h3>{{ $t('知识库引用') }}</h3><pre class="json-result">{{JSON.stringify(job.result.citations||[],null,2)}}</pre></el-tab-pane><el-tab-pane name="files" :label="$t('截图 / 视频 / Trace')"><p class="helper">截图可直接预览，点击图片可放大；视频可直接播放，下载链接仍保留。</p><div v-if="previewFiles.length" class="artifact-preview-grid"><figure v-for="f in previewFiles" :key="f.id" class="artifact-preview"><el-image v-if="f.category==='screenshot'" :src="inlineUrl(f)" :preview-src-list="screenshotUrls" :initial-index="screenshotIndex(f)" fit="contain" preview-teleported/><video v-else-if="f.category==='video'" :src="inlineUrl(f)" controls preload="metadata" playsinline/><figcaption><span>{{f.name}}</span><a :href="f.url">下载</a></figcaption></figure></div><div v-for="f in otherFiles" :key="f.id" class="file-row"><Icon name="Paperclip"/><a :href="f.url">{{f.name}}</a><span class="mini-badge">{{f.category}}</span></div><el-empty v-if="!job.files.length" :description="$t('暂无执行产物')" :image-size="70"/></el-tab-pane></el-tabs></section></div>
</template>
